  if (!key_or_array.isString()) {
    throw_invalid_argument("apc key: (not a string)");
    return false;
  }
  String strKey = key_or_array.toString();
  if (isKeyInvalid(strKey)) {
    return false;
  }
  return apc_store().add(strKey, var, ttl);
